import random


def generate(seed: int = 0) -> list[str]:
    """All generated arguments stay within the statement bounds and follow the problem guarantees."""
    rng = random.Random(seed)
    cases = [[7, 1, 5, 3, 6, 4], [7, 6, 4, 3, 1], [1], [5, 5]]
    seen = {tuple(x) for x in cases}
    while len(cases) < 600:
        a = [rng.randint(0, 10000) for _ in range(rng.randint(1, 100))]
        k = tuple(a)
        if k not in seen:
            seen.add(k)
            cases.append(a)
    return [f"candidate(prices={x!r})" for x in cases]


